package main

import (
	"fmt"
	"sync"
)

func worker(id int, wg *sync.WaitGroup) {
	defer wg.Done()                 // signal completion when this returns
	fmt.Printf("worker %d done\n", id)
}

func main() {
	var wg sync.WaitGroup           // zero value is ready to use
	for i := 1; i <= 3; i++ {
		wg.Add(1)                   // increment BEFORE launching
		go worker(i, &wg)           // pass i as an argument (no capture bug)
	}
	wg.Wait()                       // block until all three call Done()
	fmt.Println("all workers done")
}

