package solution

import "testing"

func TestSolve(t *testing.T) {
	cases := []struct {
		nums    []int
		workers int
		want    int
	}{
		{[]int{1, 2, 3, 4, 5}, 3, 15},
		{[]int{}, 4, 0},
		{[]int{10, -3, -7}, 1, 0},
	}
	for _, c := range cases {
		if got := Solve(c.nums, c.workers); got != c.want {
			t.Errorf("Solve(%v,%d)=%d want %d", c.nums, c.workers, got, c.want)
		}
	}
}

