	}()
	wg.Wait() // block until the goroutine finishes
}

func RunAll(tasks []func() int) []int {
	res := make([]int, len(tasks))   // pre-sized; each index written once
	var wg sync.WaitGroup
	for i, task := range tasks {
		wg.Add(1)
		go func(idx int, fn func() int) {  // copy idx & fn per goroutine
			defer wg.Done()
			res[idx] = fn()           // distinct index -> no data race
		}(i, task)
	}
	wg.Wait()
	return res
}
